const dias = ["Seg", "Ter", "Qua", "Qui", "Sex", "Sáb", "Dom"];
const vendas = [320, 180, 0, 450, 510, 390, 0];
const META = 300;

let total = 0;
let diasNaMeta = 0;
let relatorio = "";

for (let i = 0; i < dias.length; i++) {
  if (vendas[i] === 0) {
    relatorio += `${dias[i]}: loja fechada\n`;
    continue;
  }

  total += vendas[i];

  if (vendas[i] >= META) {
    diasNaMeta++;
    relatorio += `${dias[i]}: R$ ${vendas[i]} (meta batida)\n`;
  } else {
    relatorio += `${dias[i]}: R$ ${vendas[i]} (abaixo da meta)\n`;
  }
}

console.log(relatorio);
console.log(`Total da semana: R$ ${total}`);
console.log(`Dias na meta: ${diasNaMeta}`);

